void bfs(int root, int n) {
    int queue[MAXN], front = 0, back = 0;
    int visited[MAXN];
    memset(visited, 0, sizeof(visited));
    queue[back++] = root;
    visited[root] = 1;
    parent[root] = -1;
    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (!visited[v]) {
                visited[v] = 1;
                parent[v] = u;
                queue[back++] = v;
            }
        }
    }
}

