public class Main {
    static List<int[]>[] tree;
    static long[] parentEdgeWeight;
    static long[] prefixSum;
    static int[] parent;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());

        tree = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            tree[i] = new ArrayList<>();
        }

        parent = new int[n];
        parent[0] = -1;

        for (int i = 1; i < n; i++) {
            st = new StringTokenizer(br.readLine());
            int p = Integer.parseInt(st.nextToken());
            parent[i] = p;
            tree[p].add(new int[]{i, 0});
        }

        parentEdgeWeight = new long[n];
        prefixSum = new long[n];
        Arrays.fill(parentEdgeWeight, 0);
        Arrays.fill(prefixSum, 0);

        StringBuilder sb = new StringBuilder();
        while (q-- > 0) {
            st = new StringTokenizer(br.readLine());
            String type = st.nextToken();
            if (type.equals("add")) {
                int v = Integer.parseInt(st.nextToken());
                int w = Integer.parseInt(st.nextToken());
                parentEdgeWeight[v] += w;
                updateSubtree(v, w);
            } else {
                int u = Integer.parseInt(st.nextToken());
                sb.append(prefixSum[u]).append("\n");
            }
        }
        System.out.print(sb);
    }

    static void updateSubtree(int node, long delta) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(node);
        while (!stack.isEmpty()) {
            int cur = stack.pop();
            prefixSum[cur] += delta;
            for (int[] child : tree[cur]) {
                stack.push(child[0]);
            }
        }
    }
}

