/*
 * Weighted rooted tree:
 *  - add(v, w): add w to the edge between v and parent[v]
 *  - getSum(u): sum of edge weights on path root -> u
 *
 * Input format is not explicitly given in the statement, so this solution
 * supports a common format:
 *
 * n
 * p1 p2 ... p(n-1)
 * q
 * <operation lines>
 *
 * where parent of node 0 is absent (root), and for i = 1..n-1, parent[i] = p_i.
 *
 * Supported operation formats:
 *   add v w
 *   getSum u
 *
 * The solution uses Euler tour + Fenwick tree:
 * If an edge (v, parent[v]) gets +w, then every node in subtree(v) has its
 * root-path sum increased by w. So we do a range add on subtree(v), and
 * getSum(u) becomes a point query at tin[u].
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class Fenwick {
        int n;
        long[] bit;

        Fenwick(int n) {
            this.n = n;
            this.bit = new long[n + 2];
        }

        void add(int idx, long delta) {
            for (int i = idx; i <= n; i += i & -i) bit[i] += delta;
        }

        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += bit[i];
            return res;
        }

        void rangeAdd(int l, int r, long delta) {
            if (l > r) return;
            add(l, delta);
            add(r + 1, -delta);
        }
    }

    static List<Integer>[] g;
    static int[] tin, tout;
    static int timer = 0;

    static void dfs(int root, int n) {
        int[] stack = new int[n];
        int[] idx = new int[n];
        int top = 0;
        stack[top++] = root;

        while (top > 0) {
            int u = stack[top - 1];
            if (idx[u] == 0) {
                tin[u] = ++timer;
            }
            if (idx[u] < g[u].size()) {
                int v = g[u].get(idx[u]++);
                stack[top++] = v;
            } else {
                tout[u] = timer;
                top--;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

        for (int i = 1; i < n; i++) {
            int p = fs.nextInt();
            g[p].add(i);
        }

        tin = new int[n];
        tout = new int[n];
        dfs(0, n);

        int q = fs.nextInt();
        Fenwick fw = new Fenwick(n);
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < q; i++) {
            String op = fs.next();
            if (op.equals("add")) {
                int v = fs.nextInt();
                long w = fs.nextLong();
                fw.rangeAdd(tin[v], tout[v], w);
            } else if (op.equals("getSum")) {
                int u = fs.nextInt();
                out.append(fw.sum(tin[u])).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

