typedef long long ll;

class Fenwick {
public:
    int n;
    vector<ll> bit;
    Fenwick(int n) : n(n), bit(n+1, 0) {}
    void add(int idx, ll delta) {
        idx++; // 1-based inside
        while (idx <= n) {
            bit[idx] += delta;
            idx += idx & -idx;
        }
    }
    ll sum(int idx) {
        idx++;
        ll res = 0;
        while (idx > 0) {
            res += bit[idx];
            idx -= idx & -idx;
        }
        return res;
    }
};

