#include <bits/stdc++.h>
using namespace std;

/*
The statement only defines the tree and the two operations conceptually,
but does not specify an input format.

A natural complete solution is:
- read n
- read parent of nodes 1..n-1 (root is 0)
- read q
- then process q queries of two types:
    add v w
    getSum u

We flatten the rooted tree with an Euler tour:
- each subtree becomes a contiguous segment [tin[v], tout[v]]
If we add w to the edge (v, parent[v]), then every node in subtree(v)
has its root-to-node path increased by w.
So:
- add(v, w) => range add on subtree(v)
- getSum(u) => point query at tin[u]

We implement this using a Fenwick tree supporting range add + point query.
*/

struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n = 0) { init(n); }
    void init(int n_) {
        n = n_;
        bit.assign(n + 1, 0);
    }
    void addPoint(int idx, long long val) {
        for (++idx; idx <= n; idx += idx & -idx) bit[idx] += val;
    }
    void rangeAdd(int l, int r, long long val) {
        if (l > r) return;
        addPoint(l, val);
        if (r + 1 < n) addPoint(r + 1, -val);
    }
    long long pointQuery(int idx) const {
        long long res = 0;
        for (++idx; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<vector<int>> g(n);
    for (int v = 1; v < n; ++v) {
        int p;
        cin >> p;
        g[p].push_back(v);
    }

    vector<int> tin(n), tout(n);
    int timer = 0;

    // iterative DFS to avoid recursion depth issues
    vector<pair<int,int>> st;
    st.push_back({0, 0});
    while (!st.empty()) {
        int v = st.back().first;
        int &i = st.back().second;
        if (i == 0) tin[v] = timer++;
        if (i < (int)g[v].size()) {
            int to = g[v][i++];
            st.push_back({to, 0});
        } else {
            tout[v] = timer - 1;
            st.pop_back();
        }
    }

    Fenwick fw(n);

    int q;
    cin >> q;
    while (q--) {
        string op;
        cin >> op;
        if (op == "add") {
            int v;
            long long w;
            cin >> v >> w;
            if (v != 0) {
                fw.rangeAdd(tin[v], tout[v], w);
            }
        } else if (op == "getSum") {
            int u;
            cin >> u;
            cout << fw.pointQuery(tin[u]) << '\n';
        }
    }

    return 0;
}
